  165:         when(mMockHandler2.asBinder()).thenReturn(mBinder2);
  166:         // Initially HVAC_TEMP is not subscribed, so should return -1.
  167:         when(mHalService.getSampleRate(HVAC_TEMP)).thenReturn(-1f);
  168:         CarPropertyValue mValue = mock(CarPropertyValue.class);
  169:         when(mHalService.getPropertySafe(HVAC_TEMP, 0)).thenReturn(mValue);
  170: 
  171:         // Register the first listener.
  172:         mService.registerListener(HVAC_TEMP, /* rate= */ SENSOR_RATE_ONCHANGE, mMockHandler1);
  173: 
  174:         // Wait until we get the on property change event for the initial value.
  175:         verify(mMockHandler1, timeout(5000)).onEvent(any());
  176: 
  177:         verify(mHalService).subscribeProperty(HVAC_TEMP, 0f);
  178:         verify(mHalService).getPropertySafe(HVAC_TEMP, 0);
  179: 
  180:         // Clean up invocation state.
  181:         clearInvocations(mHalService);
  182:         when(mHalService.getSampleRate(HVAC_TEMP)).thenReturn(0f);
  183: 
  184:         // Register the second listener.
  185:         mService.registerListener(HVAC_TEMP, /* rate= */ SENSOR_RATE_ONCHANGE, mMockHandler2);
  186: 
  187:         // Wait until we get the on property change event for the initial value.
  188:         verify(mMockHandler2, timeout(5000)).onEvent(any());
  189: 
  190:         // Must not subscribe again.
  191:         verify(mHalService, never()).subscribeProperty(anyInt(), anyFloat());
  192:         verify(mHalService).getPropertySafe(HVAC_TEMP, 0);
  193: 
  194:         // Clean up invocation state.
  195:         clearInvocations(mHalService);
  196: 
  197:         // Unregister the second listener, the first listener must still be registered.
  198:         mService.unregisterListener(HVAC_TEMP, mMockHandler2);
  199: 
  200:         // The property must not be unsubscribed.
  201:         verify(mHalService, never()).unsubscribeProperty(anyInt());
  202: 
  203:         // Unregister the first listener. We have no more listeners, must cause unsubscription.
  204:         mService.unregisterListener(HVAC_TEMP, mMockHandler1);
  205: 
  206:         verify(mHalService).unsubscribeProperty(HVAC_TEMP);
  207:     }
  208: 
  209:     private static class EventListener extends ICarPropertyEventListener.Stub{
  210:         private final CarPropertyService mService;
  211:         private List<CarPropertyEvent> mEvents;
  212:         private Exception mException;
  213: 
  214:         EventListener(CarPropertyService service) {
  215:             mService = service;
  216:         }
  217: 
  218:         @Override
  219:         public void onEvent(List<CarPropertyEvent> events) throws RemoteException {
  220:             CountDownLatch latch = new CountDownLatch(1);
  221:             new Thread(() -> {
  222:                 // Call a function in CarPropertyService to make sure there is no dead lock. This
  223:                 // call doesn't actually do anything. We must use a new thread here because
  224:                 // the same thread can obtain the same lock again even if there is a dead lock.
  225:                 mService.getReadPermission(0);
  226:                 latch.countDown();
  227:             }, "onEventThread").start();
  228:             try {
  229:                 if (!latch.await(5, TimeUnit.SECONDS)) {
  230:                     mException = new Exception("timeout waiting for getReadPermission, dead lock?");
  231:                     return;
  232:                 }
  233:             } catch (InterruptedException e) {
  234:                 Thread.currentThread().interrupt();
  235:                 mException = new Exception("waiting for onEvent thread interrupted");
  236:                 return;
  237:             }
  238:             mEvents = events;
  239:         }
